insert into public.academy_lessons(id,course_id,title,slug,summary,content_html,starter_code,exercise,status,sort_order,estimated_minutes)
select x.id,c.id,x.title,x.slug,x.summary,x.content_html,x.starter_code,x.exercise,x.status,x.sort_order,x.estimated_minutes
from jsonb_to_recordset($lessons$[{"id":"curriculum-324-javascript-01","course_id":"javascript","title":"اجرای JavaScript در مرورگر","slug":"javascript-beginner-01","summary":"مرورگر کد JavaScript را اجرا می‌کند و کنسول محل مشاهده خروجی و خطاهای اولیه است.","content_html":"<h3>هدف درس</h3><p>مرورگر کد JavaScript را اجرا می‌کند و کنسول محل مشاهده خروجی و خطاهای اولیه است.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>console.log(\"سلام از JavaScript\");\nconsole.log(\"NEXORA FORGE\");</code></pre><h3>تمرین عملی</h3><p>دو پیام تازه چاپ کن و ترتیب نمایش آن‌ها را توضیح بده.</p><h3>نکته فنی</h3><p>console.log خروجی را در کنسول نشان می‌دهد، نه داخل صفحه وب.</p><h3>معیار موفقیت</h3><p>دو پیام به ترتیب در Console دیده شوند و محل اجرای کد را نشان بدهی.</p>","starter_code":"console.log(\"سلام از JavaScript\");\nconsole.log(\"NEXORA FORGE\");","exercise":"دو پیام تازه چاپ کن و ترتیب نمایش آن‌ها را توضیح بده.","status":"published","sort_order":1,"estimated_minutes":25},{"id":"curriculum-324-javascript-02","course_id":"javascript","title":"اتصال فایل خارجی با defer","slug":"javascript-beginner-02","summary":"فایل JavaScript را جداگانه نگه دار و با script متصل کن؛ defer اجرای آن را تا پایان تحلیل HTML عقب می‌اندازد.","content_html":"<h3>هدف درس</h3><p>فایل JavaScript را جداگانه نگه دار و با script متصل کن؛ defer اجرای آن را تا پایان تحلیل HTML عقب می‌اندازد.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>// در head سند:\n// &lt;script src=\"app.js\" defer&gt;&lt;/script&gt;\nconsole.log(\"app.js اجرا شد\");</code></pre><h3>تمرین عملی</h3><p>فایل app.js بساز، آن را با defer متصل کن و پیام اختصاصی نمایش بده.</p><h3>نکته فنی</h3><p>defer برای اسکریپت خارجی مناسب است؛ async ترتیب اجرای فایل‌ها را تضمین نمی‌کند.</p><h3>معیار موفقیت</h3><p>فایل app.js بدون خطای مسیر بارگذاری شود و پیام آن دیده شود.</p>","starter_code":"// در head سند:\n// <script src=\"app.js\" defer></script>\nconsole.log(\"app.js اجرا شد\");","exercise":"فایل app.js بساز، آن را با defer متصل کن و پیام اختصاصی نمایش بده.","status":"published","sort_order":2,"estimated_minutes":25},{"id":"curriculum-324-javascript-03","course_id":"javascript","title":"نخستین دستورها","slug":"javascript-beginner-03","summary":"دستورهای JavaScript به ترتیب اجرا می‌شوند. نوشتن هر دستور در خط جدا خواندن کد را آسان می‌کند.","content_html":"<h3>هدف درس</h3><p>دستورهای JavaScript به ترتیب اجرا می‌شوند. نوشتن هر دستور در خط جدا خواندن کد را آسان می‌کند.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>console.log(\"نام پروژه\");\nconsole.log(\"NEXORA FORGE\");\nconsole.log(\"نسخه آزمایشی 1\");</code></pre><h3>تمرین عملی</h3><p>سه دستور برای نام، هدف و نسخه پروژه بنویس.</p><h3>نکته فنی</h3><p>هر دستور را جداگانه اجرا کن تا ترتیب و محل خطا مشخص باشد.</p><h3>معیار موفقیت</h3><p>سه پیام دقیقاً به ترتیب نوشته‌شده نمایش داده شوند.</p>","starter_code":"console.log(\"نام پروژه\");\nconsole.log(\"NEXORA FORGE\");\nconsole.log(\"نسخه آزمایشی 1\");","exercise":"سه دستور برای نام، هدف و نسخه پروژه بنویس.","status":"published","sort_order":3,"estimated_minutes":25},{"id":"curriculum-324-javascript-04","course_id":"javascript","title":"کنسول و پیام‌های تشخیصی","slug":"javascript-beginner-04","summary":"کنسول برای مشاهده مقدارها و خطاهاست. log، warn و error پیام‌ها را با سطح متفاوت نمایش می‌دهند.","content_html":"<h3>هدف درس</h3><p>کنسول برای مشاهده مقدارها و خطاهاست. log، warn و error پیام‌ها را با سطح متفاوت نمایش می‌دهند.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>console.log(\"اطلاعات\");\nconsole.warn(\"هشدار آزمایشی\");\nconsole.error(\"خطای نمونه\");</code></pre><h3>تمرین عملی</h3><p>سه نوع پیام بساز و تفاوت نمایش آن‌ها را در DevTools بررسی کن.</p><h3>نکته فنی</h3><p>console.error پیام خطا را نمایش می‌دهد اما به‌تنهایی اجرای برنامه را متوقف نمی‌کند.</p><h3>معیار موفقیت</h3><p>تفاوت ظاهر و کاربرد log، warn و error را توضیح بدهی.</p>","starter_code":"console.log(\"اطلاعات\");\nconsole.warn(\"هشدار آزمایشی\");\nconsole.error(\"خطای نمونه\");","exercise":"سه نوع پیام بساز و تفاوت نمایش آن‌ها را در DevTools بررسی کن.","status":"published","sort_order":4,"estimated_minutes":25},{"id":"curriculum-324-javascript-05","course_id":"javascript","title":"متغیرها با let و const","slug":"javascript-beginner-05","summary":"const برای متغیری است که دوباره انتساب نمی‌گیرد و let برای مقداری است که تغییر می‌کند.","content_html":"<h3>هدف درس</h3><p>const برای متغیری است که دوباره انتساب نمی‌گیرد و let برای مقداری است که تغییر می‌کند.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const academy = \"NEXORA FORGE\";\nlet completed = 0;\ncompleted = completed + 1;\nconsole.log(academy, completed);</code></pre><h3>تمرین عملی</h3><p>نام آکادمی را با const و شمارنده درس را با let تعریف و سه بار افزایش بده.</p><h3>نکته فنی</h3><p>const انتساب دوباره را محدود می‌کند، نه تغییر محتوای شیء یا آرایه را.</p><h3>معیار موفقیت</h3><p>مقدار academy ثابت بماند و شمارنده با let افزایش پیدا کند.</p>","starter_code":"const academy = \"NEXORA FORGE\";\nlet completed = 0;\ncompleted = completed + 1;\nconsole.log(academy, completed);","exercise":"نام آکادمی را با const و شمارنده درس را با let تعریف و سه بار افزایش بده.","status":"published","sort_order":5,"estimated_minutes":25},{"id":"curriculum-324-javascript-06","course_id":"javascript","title":"نام‌گذاری متغیرها","slug":"javascript-beginner-06","summary":"نام متغیر باید معتبر و معنادار باشد. JavaScript به بزرگی و کوچکی حروف حساس است.","content_html":"<h3>هدف درس</h3><p>نام متغیر باید معتبر و معنادار باشد. JavaScript به بزرگی و کوچکی حروف حساس است.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const studentName = \"سارا\";\nconst lessonCount = 12;\nconst isActive = true;\nconsole.log(studentName, lessonCount, isActive);</code></pre><h3>تمرین عملی</h3><p>نام‌های a و x را با نام‌های روشن و معنادار جایگزین کن.</p><h3>نکته فنی</h3><p>JavaScript به بزرگی و کوچکی حروف حساس است و نام‌های رزروشده قابل استفاده نیستند.</p><h3>معیار موفقیت</h3><p>نام‌ها معتبر باشند و از روی هر نام نقش متغیر مشخص شود.</p>","starter_code":"const studentName = \"سارا\";\nconst lessonCount = 12;\nconst isActive = true;\nconsole.log(studentName, lessonCount, isActive);","exercise":"نام‌های a و x را با نام‌های روشن و معنادار جایگزین کن.","status":"published","sort_order":6,"estimated_minutes":25},{"id":"curriculum-324-javascript-07","course_id":"javascript","title":"رشته‌ها و طول متن","slug":"javascript-beginner-07","summary":"رشته برای نگهداری متن است. typeof نوع داده را نشان می‌دهد و length طول رشته را گزارش می‌کند.","content_html":"<h3>هدف درس</h3><p>رشته برای نگهداری متن است. typeof نوع داده را نشان می‌دهد و length طول رشته را گزارش می‌کند.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const student = \"مینا\";\nconst course = 'JavaScript';\nconsole.log(typeof student, student.length);\nconsole.log(course.length);</code></pre><h3>تمرین عملی</h3><p>نام و عنوان دوره را ذخیره کن و نوع و طول هر دو را چاپ کن.</p><h3>نکته فنی</h3><p>length تعداد واحدهای UTF-16 را می‌شمارد و همیشه برابر نویسه‌های دیداری نیست.</p><h3>معیار موفقیت</h3><p>نوع هر مقدار string باشد و طول آن درست از length خوانده شود.</p>","starter_code":"const student = \"مینا\";\nconst course = 'JavaScript';\nconsole.log(typeof student, student.length);\nconsole.log(course.length);","exercise":"نام و عنوان دوره را ذخیره کن و نوع و طول هر دو را چاپ کن.","status":"published","sort_order":7,"estimated_minutes":25},{"id":"curriculum-324-javascript-08","course_id":"javascript","title":"عدد و محاسبات پایه","slug":"javascript-beginner-08","summary":"نوع Number برای عدد صحیح و اعشاری استفاده می‌شود. عملگرهای ریاضی محاسبات پایه را انجام می‌دهند.","content_html":"<h3>هدف درس</h3><p>نوع Number برای عدد صحیح و اعشاری استفاده می‌شود. عملگرهای ریاضی محاسبات پایه را انجام می‌دهند.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const price = 125;\nconst count = 3;\nconsole.log(price * count);\nconsole.log(17 % 5);</code></pre><h3>تمرین عملی</h3><p>هزینه چهار قلم را محاسبه کن و باقیمانده تقسیم ۲۳ بر ۴ را چاپ کن.</p><h3>نکته فنی</h3><p>عملگر % باقیمانده تقسیم را می‌دهد؛ در محاسبات اعشاری محدودیت دقت Number را در نظر بگیر.</p><h3>معیار موفقیت</h3><p>ضرب و باقیمانده با محاسبه دستی برابر باشند.</p>","starter_code":"const price = 125;\nconst count = 3;\nconsole.log(price * count);\nconsole.log(17 % 5);","exercise":"هزینه چهار قلم را محاسبه کن و باقیمانده تقسیم ۲۳ بر ۴ را چاپ کن.","status":"published","sort_order":8,"estimated_minutes":25},{"id":"curriculum-324-javascript-09","course_id":"javascript","title":"تبدیل نوع داده","slug":"javascript-beginner-09","summary":"Number و String تبدیل صریح انجام می‌دهند. ورودی نامعتبر باید بررسی شود تا محاسبه اشتباه انجام نشود.","content_html":"<h3>هدف درس</h3><p>Number و String تبدیل صریح انجام می‌دهند. ورودی نامعتبر باید بررسی شود تا محاسبه اشتباه انجام نشود.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const raw = \"17\";\nconst score = Number(raw);\nconsole.log(score + 3);\nconsole.log(String(score));\nconsole.log(Number.isNaN(Number(\"هفده\")));</code></pre><h3>تمرین عملی</h3><p>ورودی عددی و غیرعددی را تبدیل کن و ورودی نامعتبر را تشخیص بده.</p><h3>نکته فنی</h3><p>Number رشته خالی را صفر می‌کند؛ ورودی را قبل از تبدیل بررسی کن.</p><h3>معیار موفقیت</h3><p>ورودی عددی به number و ورودی نامعتبر به‌درستی شناسایی شود.</p>","starter_code":"const raw = \"17\";\nconst score = Number(raw);\nconsole.log(score + 3);\nconsole.log(String(score));\nconsole.log(Number.isNaN(Number(\"هفده\")));","exercise":"ورودی عددی و غیرعددی را تبدیل کن و ورودی نامعتبر را تشخیص بده.","status":"published","sort_order":9,"estimated_minutes":25},{"id":"curriculum-324-javascript-10","course_id":"javascript","title":"عملگرهای مقایسه","slug":"javascript-beginner-10","summary":"عملگرهای مقایسه نتیجه Boolean می‌دهند. === هم مقدار و هم نوع را می‌سنجد.","content_html":"<h3>هدف درس</h3><p>عملگرهای مقایسه نتیجه Boolean می‌دهند. === هم مقدار و هم نوع را می‌سنجد.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>console.log(10 === \"10\");\nconsole.log(10 !== 8);\nconsole.log(15 &gt;= 12);\nconsole.log(7 &lt; 3);</code></pre><h3>تمرین عملی</h3><p>نمره را با چند حد مقایسه کن و نتیجه عبارت‌ها را پیش از اجرا پیش‌بینی کن.</p><h3>نکته فنی</h3><p>=== و !== از تبدیل ضمنی نوع جلوگیری می‌کنند و معمولاً انتخاب امن‌تری هستند.</p><h3>معیار موفقیت</h3><p>نتیجه هر چهار مقایسه را پیش از اجرا درست پیش‌بینی کنی.</p>","starter_code":"console.log(10 === \"10\");\nconsole.log(10 !== 8);\nconsole.log(15 >= 12);\nconsole.log(7 < 3);","exercise":"نمره را با چند حد مقایسه کن و نتیجه عبارت‌ها را پیش از اجرا پیش‌بینی کن.","status":"published","sort_order":10,"estimated_minutes":25},{"id":"curriculum-324-javascript-11","course_id":"javascript","title":"عملگرهای منطقی","slug":"javascript-beginner-11","summary":"&&، || و ! برای ترکیب شرط‌ها یا معکوس کردن نتیجه منطقی استفاده می‌شوند.","content_html":"<h3>هدف درس</h3><p>&&، || و ! برای ترکیب شرط‌ها یا معکوس کردن نتیجه منطقی استفاده می‌شوند.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const loggedIn = true;\nconst active = false;\nconsole.log(loggedIn &amp;&amp; active);\nconsole.log(loggedIn || active);\nconsole.log(!active);</code></pre><h3>تمرین عملی</h3><p>شرط دسترسی به درس را با ورود و فعال بودن حساب بساز.</p><h3>نکته فنی</h3><p>&& و || از ارزیابی کوتاه‌شونده استفاده می‌کنند؛ سمت راست ممکن است اجرا نشود.</p><h3>معیار موفقیت</h3><p>شرط دسترسی فقط وقتی true شود که هر دو وضعیت لازم برقرار باشند.</p>","starter_code":"const loggedIn = true;\nconst active = false;\nconsole.log(loggedIn && active);\nconsole.log(loggedIn || active);\nconsole.log(!active);","exercise":"شرط دسترسی به درس را با ورود و فعال بودن حساب بساز.","status":"published","sort_order":11,"estimated_minutes":25},{"id":"curriculum-324-javascript-12","course_id":"javascript","title":"شرط if","slug":"javascript-beginner-12","summary":"if یک بلوک کد را فقط زمانی اجرا می‌کند که شرط درست باشد.","content_html":"<h3>هدف درس</h3><p>if یک بلوک کد را فقط زمانی اجرا می‌کند که شرط درست باشد.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const score = 82;\nif (score &gt;= 60) {\n  console.log(\"قبول شدی\");\n}</code></pre><h3>تمرین عملی</h3><p>اگر حداقل پنج درس تکمیل شده بود پیام پیشرفت چاپ کن.</p><h3>نکته فنی</h3><p>شرط را داخل پرانتز و بدنه را داخل آکولاد قرار بده؛ مرزهای شرط را آزمایش کن.</p><h3>معیار موفقیت</h3><p>نمره کمتر از ۶۰ پیام رد و نمره ۶۰ یا بیشتر پیام قبولی بدهد.</p>","starter_code":"const score = 82;\nif (score >= 60) {\n  console.log(\"قبول شدی\");\n}","exercise":"اگر حداقل پنج درس تکمیل شده بود پیام پیشرفت چاپ کن.","status":"published","sort_order":12,"estimated_minutes":25},{"id":"curriculum-324-javascript-13","course_id":"javascript","title":"مسیر جایگزین else","slug":"javascript-beginner-13","summary":"else زمانی اجرا می‌شود که شرط if درست نباشد و دو مسیر تصمیم‌گیری را پوشش می‌دهد.","content_html":"<h3>هدف درس</h3><p>else زمانی اجرا می‌شود که شرط if درست نباشد و دو مسیر تصمیم‌گیری را پوشش می‌دهد.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const balance = 40;\nif (balance &gt;= 50) {\n  console.log(\"اعتبار کافی است\");\n} else {\n  console.log(\"اعتبار کافی نیست\");\n}</code></pre><h3>تمرین عملی</h3><p>برای اعتبار حساب دو پیام متفاوت بنویس و هر دو مسیر را آزمایش کن.</p><h3>نکته فنی</h3><p>else شرط مستقلی ندارد و فقط زمانی اجرا می‌شود که if متناظر false باشد.</p><h3>معیار موفقیت</h3><p>هر دو مسیر با تغییر موجودی اجرا شوند و پیام درست نمایش داده شود.</p>","starter_code":"const balance = 40;\nif (balance >= 50) {\n  console.log(\"اعتبار کافی است\");\n} else {\n  console.log(\"اعتبار کافی نیست\");\n}","exercise":"برای اعتبار حساب دو پیام متفاوت بنویس و هر دو مسیر را آزمایش کن.","status":"published","sort_order":13,"estimated_minutes":25},{"id":"curriculum-324-javascript-14","course_id":"javascript","title":"چند حالت با else if","slug":"javascript-beginner-14","summary":"زنجیره else if چند بازه را بررسی می‌کند. ترتیب شرط‌ها مهم است و شرط خاص باید پیش از شرط عمومی قرار گیرد.","content_html":"<h3>هدف درس</h3><p>زنجیره else if چند بازه را بررسی می‌کند. ترتیب شرط‌ها مهم است و شرط خاص باید پیش از شرط عمومی قرار گیرد.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const score = 76;\nif (score &gt;= 90) console.log(\"عالی\");\nelse if (score &gt;= 70) console.log(\"خوب\");\nelse if (score &gt;= 50) console.log(\"نیازمند تمرین\");\nelse console.log(\"شروع دوباره\");</code></pre><h3>تمرین عملی</h3><p>رده‌بندی چهارسطحی بساز و مرزهای ۴۹، ۵۰، ۶۹، ۷۰ و ۹۰ را آزمایش کن.</p><h3>نکته فنی</h3><p>پس از اولین شرط درست، بقیه شاخه‌های else if بررسی نمی‌شوند.</p><h3>معیار موفقیت</h3><p>نمره‌های مرزی ۴۹، ۵۰، ۶۹، ۷۰ و ۹۰ در دسته صحیح قرار بگیرند.</p>","starter_code":"const score = 76;\nif (score >= 90) console.log(\"عالی\");\nelse if (score >= 70) console.log(\"خوب\");\nelse if (score >= 50) console.log(\"نیازمند تمرین\");\nelse console.log(\"شروع دوباره\");","exercise":"رده‌بندی چهارسطحی بساز و مرزهای ۴۹، ۵۰، ۶۹، ۷۰ و ۹۰ را آزمایش کن.","status":"published","sort_order":14,"estimated_minutes":25},{"id":"curriculum-324-javascript-15","course_id":"javascript","title":"انتخاب حالت با switch","slug":"javascript-beginner-15","summary":"switch برای انتخاب بین مقدارهای مشخص مناسب است. break مانع ادامه ناخواسته به case بعدی می‌شود.","content_html":"<h3>هدف درس</h3><p>switch برای انتخاب بین مقدارهای مشخص مناسب است. break مانع ادامه ناخواسته به case بعدی می‌شود.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const level = \"intermediate\";\nswitch (level) {\n case \"beginner\": console.log(\"مقدماتی\"); break;\n case \"intermediate\": console.log(\"متوسط\"); break;\n case \"advanced\": console.log(\"پیشرفته\"); break;\n default: console.log(\"ناشناخته\");\n}</code></pre><h3>تمرین عملی</h3><p>برای سه وضعیت سفارش و یک مقدار ناشناخته switch بنویس.</p><h3>نکته فنی</h3><p>switch با تطبیق سخت‌گیرانه کار می‌کند؛ break از fall-through ناخواسته جلوگیری می‌کند.</p><h3>معیار موفقیت</h3><p>سه case و مسیر default خروجی متناسب با مقدار داشته باشند.</p>","starter_code":"const level = \"intermediate\";\nswitch (level) {\n case \"beginner\": console.log(\"مقدماتی\"); break;\n case \"intermediate\": console.log(\"متوسط\"); break;\n case \"advanced\": console.log(\"پیشرفته\"); break;\n default: console.log(\"ناشناخته\");\n}","exercise":"برای سه وضعیت سفارش و یک مقدار ناشناخته switch بنویس.","status":"published","sort_order":15,"estimated_minutes":25},{"id":"curriculum-324-javascript-16","course_id":"javascript","title":"حلقه for","slug":"javascript-beginner-16","summary":"for برای تکرار تعداد مشخصی از دفعات مناسب است. مقدار آغاز، شرط ادامه و تغییر شمارنده در یک ساختار قرار دارند.","content_html":"<h3>هدف درس</h3><p>for برای تکرار تعداد مشخصی از دفعات مناسب است. مقدار آغاز، شرط ادامه و تغییر شمارنده در یک ساختار قرار دارند.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>for (let lesson = 1; lesson &lt;= 5; lesson++) {\n  console.log(\"درس\", lesson);\n}</code></pre><h3>تمرین عملی</h3><p>شماره درس‌های ۱ تا ۱۰ را چاپ کن و سپس فقط عددهای زوج را نمایش بده.</p><h3>نکته فنی</h3><p>شرط پایان را دقیق انتخاب کن؛ خطای یک‌واحدی می‌تواند یک دور اضافه یا کمتر ایجاد کند.</p><h3>معیار موفقیت</h3><p>شماره‌های ۱ تا ۵ دقیقاً یک بار چاپ شوند.</p>","starter_code":"for (let lesson = 1; lesson <= 5; lesson++) {\n  console.log(\"درس\", lesson);\n}","exercise":"شماره درس‌های ۱ تا ۱۰ را چاپ کن و سپس فقط عددهای زوج را نمایش بده.","status":"published","sort_order":16,"estimated_minutes":25},{"id":"curriculum-324-javascript-17","course_id":"javascript","title":"حلقه while","slug":"javascript-beginner-17","summary":"while پیش از اجرای بدنه شرط را می‌سنجد؛ تغییر متغیر کنترل برای توقف حلقه ضروری است.","content_html":"<h3>هدف درس</h3><p>while پیش از اجرای بدنه شرط را می‌سنجد؛ تغییر متغیر کنترل برای توقف حلقه ضروری است.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>let attempts = 0;\nwhile (attempts &lt; 3) {\n  console.log(\"تلاش\", attempts + 1);\n  attempts++;\n}</code></pre><h3>تمرین عملی</h3><p>شمارش معکوس از پنج تا یک را با while انجام بده.</p><h3>نکته فنی</h3><p>اگر متغیر کنترل تغییر نکند، حلقه while ممکن است بی‌نهایت شود.</p><h3>معیار موفقیت</h3><p>حلقه پس از سه تلاش متوقف شود و شمارنده افزایش یافته باشد.</p>","starter_code":"let attempts = 0;\nwhile (attempts < 3) {\n  console.log(\"تلاش\", attempts + 1);\n  attempts++;\n}","exercise":"شمارش معکوس از پنج تا یک را با while انجام بده.","status":"published","sort_order":17,"estimated_minutes":25},{"id":"curriculum-324-javascript-18","course_id":"javascript","title":"ساخت آرایه و اندیس","slug":"javascript-beginner-18","summary":"آرایه مجموعه‌ای مرتب از مقدارهاست و اندیس آن از صفر آغاز می‌شود. length تعداد عناصر را می‌دهد.","content_html":"<h3>هدف درس</h3><p>آرایه مجموعه‌ای مرتب از مقدارهاست و اندیس آن از صفر آغاز می‌شود. length تعداد عناصر را می‌دهد.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const courses = [\"HTML\", \"CSS\", \"JavaScript\"];\nconsole.log(courses[0]);\nconsole.log(courses[2]);\nconsole.log(courses.length);</code></pre><h3>تمرین عملی</h3><p>آرایه‌ای از پنج درس بساز و اولین، سومین و آخرین مقدار را چاپ کن.</p><h3>نکته فنی</h3><p>اندیس آرایه از صفر آغاز می‌شود؛ اندیس خارج از محدوده معمولاً undefined می‌دهد.</p><h3>معیار موفقیت</h3><p>اولین، سومین و آخرین درس درست نمایش داده شوند.</p>","starter_code":"const courses = [\"HTML\", \"CSS\", \"JavaScript\"];\nconsole.log(courses[0]);\nconsole.log(courses[2]);\nconsole.log(courses.length);","exercise":"آرایه‌ای از پنج درس بساز و اولین، سومین و آخرین مقدار را چاپ کن.","status":"published","sort_order":18,"estimated_minutes":25}]$lessons$::jsonb) as x(id text,course_id text,title text,slug text,summary text,content_html text,starter_code text,exercise text,status text,sort_order integer,estimated_minutes integer)
join (values
('html','html','beginner'),('html-intermediate','html','intermediate'),('html-advanced','html','advanced'),
('css','css','beginner'),('css-intermediate','css','intermediate'),('css-advanced','css','advanced'),
('javascript','javascript','beginner'),('javascript-intermediate','javascript','intermediate'),('javascript-advanced','javascript','advanced')
) as cp(course_id,language_id,level_id) on cp.course_id=x.course_id
join public.academy_courses c on c.language_id=cp.language_id and c.level_id=cp.level_id
on conflict(id) do update set title=excluded.title,slug=excluded.slug,summary=excluded.summary,content_html=excluded.content_html,starter_code=excluded.starter_code,exercise=excluded.exercise,status='published',sort_order=excluded.sort_order,estimated_minutes=excluded.estimated_minutes,archived_at=null,updated_at=now();
commit;
